      [['Mop the floors', 3], ['Grocery shopping', 2]].forEach(function (it, i) { hist('B', ws + (10 + i) * HOUR, it[0], it[1], i === 0 ? { note: 'Floors: spotless. Unlike your record.' } : null); });
