  // App resume: when the app comes back after being away, replay what the partner earned meanwhile.
  function toggleApp() { }
  function noteAway() {
    if (!S || !S.members[ME] || !SYNC.code) return;
    var T = now(), o = other(ME);
    var a = { at: T, p: hasPartner(ME) ? weekXP(o, T) : 0, me: weekXP(ME, T), ws: weekStart(T) };
    try { localStorage.setItem('hb-away-' + SYNC.code + '-' + ME, JSON.stringify(a)); } catch (e) { }
  }
  function checkCatchup() {
    if (!S || !S.members[ME] || !SYNC.code) return;
    var ui = UI[ME], a = null;
    try { a = JSON.parse(localStorage.getItem('hb-away-' + SYNC.code + '-' + ME) || 'null'); } catch (e) { }
    try { localStorage.removeItem('hb-away-' + SYNC.code + '-' + ME); } catch (e) { }
    if (!a) return;
    var T = now(), o = other(ME);
    if (T - a.at > 10 * MIN) { nextTip(ME); ui.intro = true; }
    if (hasPartner(ME) && !isPaused() && a.ws === weekStart(T) && !ui.sheet && !ui.settings) {
      var items = compsBy(o).filter(function (c) { return c.at > a.at && c.at <= T; }).sort(function (x, y) { return x.at - y.at; });
      var np = weekXP(o, T), me = weekXP(ME, T);
      if (items.length && np > a.p) { ui.tab = 'tasks'; ui.catchup = { from: a.p, to: np, me: me, items: items, tookLead: a.p <= a.me && np > me, started: false }; }
    }
    renderPhone(ME);
  }

  function tween(el, from, to, dur) {
    var start = null;
    function step(ts) { if (start === null) start = ts; var k = Math.min(1, (ts - start) / dur); el.textContent = Math.round(from + (to - from) * k); if (k < 1) requestAnimationFrame(step); }
    requestAnimationFrame(step);
  }
  function runCatchup(pid) {
    var ui = UI[pid], cu = ui.catchup; if (!cu) return;
    var root = phoneEl[pid], app = root.querySelector('.app'), scoreEl = root.querySelector('[data-pscore]'), hdr = root.querySelector('.hdr');
    if (!app || !scoreEl || !hdr) { ui.catchup = null; return; }
    var tug = hdr.querySelector('.tug'), tugL = tug && tug.querySelector('.l');
    var total = cu.me + cu.to, toPct = total ? Math.round(cu.me / total * 100) : 50;
    ui.animLock = true;
    var timers = ui.catchTimers = [];
    var later = function (fn, ms) { timers.push(setTimeout(fn, ms)); };
    function finish() { timers.forEach(clearTimeout); ui.animLock = false; ui.catchup = null; ui.catchTimers = null; ui.skipCatchup = null; renderPhone(pid); }
    ui.skipCatchup = finish;
    function stamp() {
      var ar = app.getBoundingClientRect(), hr = hdr.getBoundingClientRect();
      var st = document.createElement('div'); st.className = 'stamp';
      st.innerHTML = esc(nameOf(other(pid))).toUpperCase() + ' TOOK<br>THE LEAD';
      st.style.top = (hr.top - ar.top + hr.height / 2) + 'px';
      app.appendChild(st); hdr.classList.add('shake');
      fxPlay(hdr.querySelector('.player:not(.right) .dogav'), 'flinch', pid);
      later(function () { st.classList.add('out'); }, 1500);
    }
    if (reduceMotion) {
      scoreEl.textContent = cu.to; if (tugL) tugL.style.width = toPct + '%';
      if (cu.tookLead) stamp();
      later(finish, cu.tookLead ? 2000 : 400); return;
    }
    var ar = app.getBoundingClientRect(), sr = scoreEl.getBoundingClientRect(), hr = hdr.getBoundingClientRect();
    var endX = sr.left - ar.left + sr.width / 2 - 9, endY = sr.top - ar.top + sr.height / 2 - 9;
    var startX = ar.width / 2 - 9, startY = hr.bottom - ar.top + 30;
    var shown = cu.items.slice(-8), pre = cu.items.slice(0, cu.items.length - shown.length).reduce(function (n, c) { return n + c.xp; }, 0);
    var cur = cu.from + pre; scoreEl.textContent = cur;
    shown.forEach(function (c, i) {
      later(function () {
        var coin = document.createElement('div'); coin.className = 'coin'; app.appendChild(coin);
        var midY = Math.min(startY, endY) - 40;
        var anim = coin.animate([
          { transform: 'translate(' + startX + 'px,' + startY + 'px) scale(0.5)', opacity: 0 },
          { transform: 'translate(' + ((startX + endX) / 2) + 'px,' + midY + 'px) scale(1.15)', opacity: 1, offset: 0.55 },
          { transform: 'translate(' + endX + 'px,' + endY + 'px) scale(0.7)', opacity: 1 }
        ], { duration: 500, easing: 'ease-in' });
        anim.onfinish = function () {
          coin.remove(); var from = cur; cur += c.xp; tween(scoreEl, from, cur, 220);
          fxPlay(hdr.querySelector('.player.right .dogav'), c.size >= 4 ? 'popshake' : 'pop', other(pid));
          scoreEl.classList.remove('bump'); void scoreEl.offsetWidth; scoreEl.classList.add('bump');
        };
      }, 250 + i * 280);
    });
    var tAfter = 250 + shown.length * 280 + 560;
    later(function () {
      scoreEl.textContent = cu.to;
      var f = document.createElement('div'); f.className = 'float-xp'; f.textContent = '+' + (cu.to - cu.from);
      f.style.left = (endX - 14) + 'px'; f.style.top = (endY - 30) + 'px'; app.appendChild(f);
      if (tug) tug.classList.add('glow');
      if (tugL) tugL.style.width = toPct + '%';
    }, tAfter);
    if (cu.tookLead) later(stamp, tAfter + 650);
    later(finish, cu.tookLead ? tAfter + 2700 : tAfter + 1400);
  }

  /* ================= Phone render ================= */
  function phoneHTML(pid) {
    if (APP.screen) return '<div class="app">' + appScreenHTML() + '</div>';
    var ui = UI[pid];
    if (!S.members[pid] && ui.ob.step === 'done') ui.ob.step = 'welcome';
    if (ui.closed && S.members[pid]) return '<div class="app">' + homeHTML(pid) + '</div>';
    if (!S.members[pid] || ui.ob.step === 'invite' || ui.ob.step === 'starter') return '<div class="app">' + onboardingHTML(pid) + '</div>';
    if (ui.tab === 'activity' && !ui.settings) { S.seen[pid] = now(); }
    var paused = isPaused();
    var main;
    if (ui.settings) main = settingsHTML(pid);
    else main = bannerHTML(pid) + installBannerHTML() + (ui.tab === 'tasks' ? tasksHTML(pid) : ui.tab === 'score' ? scoreHTML(pid) : activityHTML(pid)) + navHTML(pid);
    var fab = ui.tab === 'tasks' && !ui.settings && !paused ? '<button class="fab" data-act="add-open" aria-label="Add task">' + IC.plus + '</button>' : '';
    maybeOpenSummary(pid);
    maybeAskNudges(pid);
    underdogNotice(pid);
    maybeOpenChest(pid);
    return '<div class="app' + (paused ? ' is-paused' : '') + '">' + (SYNC.status === 'offline' ? '<div class="netbar" role="status">Offline. Your changes will sync when you\'re back online.</div>' : '') + main + fab + (ui.settings ? '' : toastHTML(pid)) + sheetHTML(pid) + dogPickerHTML(pid) + chestHTML(pid) + udModalHTML(pid) + weekSumHTML(pid) + notifHTML(pid) + '</div>';
  }

  var phoneEl = {}, reduceMotion = false;
  try { reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { }

  // Filter chips scroll sideways: touch swipe, mouse wheel, mouse drag. Fades show there's more.
  function chipFades(el) {
    var max = el.scrollWidth - el.clientWidth;
    el.classList.toggle('fl', el.scrollLeft > 2);
    el.classList.toggle('fr', el.scrollLeft < max - 2);
  }
  function wireChips(el) {
    chipFades(el);
    el.addEventListener('scroll', function () { chipFades(el); }, { passive: true });
    el.addEventListener('wheel', function (e) {
      if (el.scrollWidth <= el.clientWidth || Math.abs(e.deltaX) > Math.abs(e.deltaY)) return;
      e.preventDefault(); el.scrollLeft += e.deltaY;
    }, { passive: false });
    var drag = null;
    el.addEventListener('pointerdown', function (e) {
      if (e.pointerType !== 'mouse' || e.button !== 0) return;
      drag = { x: e.clientX, left: el.scrollLeft, moved: false };
    });
    el.addEventListener('pointermove', function (e) {
      if (!drag) return;
      var dx = e.clientX - drag.x;
      if (Math.abs(dx) > 5) { drag.moved = true; el.classList.add('dragging'); }
      if (drag.moved) el.scrollLeft = drag.left - dx;
    });
    function end() { if (drag && drag.moved) { el.dataset.justDragged = '1'; setTimeout(function () { delete el.dataset.justDragged; }, 0); } drag = null; el.classList.remove('dragging'); }
    el.addEventListener('pointerup', end); el.addEventListener('pointerleave', end);
    el.addEventListener('click', function (e) { if (el.dataset.justDragged) { e.stopPropagation(); e.preventDefault(); } }, true);
  }

  /* ---------- 0.2.0: vibration ---------- */
